202	              <span aria-hidden="true">🔒</span> Exclusive Access
203	            </div>
204	          </div>
205	          <h2 id="beta-cta-heading" className={styles["whiteHeading"]}>
206	            Private Beta Pricing
207	          </h2>
208	          <p className={styles["betaSectionDesc"]}>
209	            Join Boldteq&apos;s private beta and experience our agency delivery
210	            infrastructure at founding pricing — before public launch moves to
211	            standard rates.
212	          </p>
213	          <div className={styles["betaBenefitsRow"]}>
214	            {LEFT_BENEFITS.map((benefit) => (
215	              <div key={benefit} className={styles["whiteLiIcon"]}>
216	                <div className={styles["liCheckSky"]}>
217	                  <Image
218	                    src="/images/webflow/Group-1.svg"
219	                    alt=""
220	                    aria-hidden="true"
221	                    width={19}
222	                    height={19}
223	                    className={styles["circleTick"]}
224	                  />
225	                </div>
226	                <p className={styles["paragraphSmallWhiteSmallFont"]}>
227	                  {benefit}
228	                </p>
229	              </div>
230	            ))}
231	          </div>
232	          <p className={styles["urgencyText"]}>
233	            Only <strong className={styles["skyBold"]}>15 agencies</strong> will
234	            be accepted in this beta round
235	          </p>
236	          <Link href="/book-a-demo" className={styles["skyButton"]}>
237	            <span aria-hidden="true">🚀</span> Join the Beta
238	          </Link>
239	        </div>
240	      </div>
241	    </section>
242	  );
243	}
